{"query":{"esql":"SET unmapped_fields="nullify";
FROM .alerts-stack.alerts-default
| WHERE kibana.alert.rule.tags == "billing" AND kibana.alert.status == "active"
| KEEP kibana.alert.rule.name, kibana.alert.start, kibana.alert.reason
| SORT kibana.alert.start DESC"},"filter":[]}

{"query":{"esql":"SET unmapped_fields="nullify";
FROM metrics-generic.otel-default*
| WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend AND metrics.billing.reconciliation.open_items IS NOT NULL
| STATS open_items = LAST(metrics.billing.reconciliation.open_items, @timestamp) BY tenant = attributes.tenant, kind = attributes.kind
| SORT open_items DESC, tenant, kind
| KEEP tenant, kind, open_items"},"filter":[]}
